def proof_links(pairs):
    bits = []
    seen = set()
    for title, url in pairs:
        url = (url or "").strip()
        if not url.startswith("http") or url in seen:
            continue
        seen.add(url)
        label = (title or "").strip() or url
        if len(label) > 88:
            label = label[:85] + "..."
        bits.append(
            '<a href="%s" target="_blank" rel="noopener">%s</a>'
            % (html.escape(url, quote=True), html.escape(label))
        )
        if len(bits) == 3:
            break
    if not bits:
        return ""
    return '<div class="links">' + "".join(bits) + "</div>"



